import{_ as d,o,c as t,ag as c}from"./chunks/framework.DXGyWiRo.js";const E=JSON.parse('{"title":"MCP 客户端集成","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/mcp.md","filePath":"zh/guide/mcp.md","lastUpdated":1792912409000}'),a={name:"zh/guide/mcp.md"};function r(i,e,l,n,s,p){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="mcp-客户端集成" tabindex="-1">MCP 客户端集成 <a class="header-anchor" href="#mcp-客户端集成" aria-label="Permalink to &quot;MCP 客户端集成&quot;">​</a></h1><p>自 v3.2.6 起，EasyYapi 向 IntelliJ IDEA 内置的 MCP（Model Context Protocol）服务器添加了两个工具，让连接到 IDE 的外部 Agent 可以驱动 EasyYapi，且全程无对话框：</p><ul><li><code>easyapi_scan_endpoints</code> —— 只读：报告 Agent 指定的类、方法或源文件对应的、EasyYapi 将会导出的端点。</li><li><code>easyapi_export</code> —— 将这些端点导出到 YApi，与<a href="./export2yapi">导出到 YApi</a>行为一致，且无任何对话框。</li></ul><p>与在 IDE 内部工作、替你编写规则的内置 AI 助手不同，这两个工具让外部 Agent 驱动正在运行的 EasyYapi。每个工具都会向客户端描述自己的参数、返回结果和错误码；本页介绍围绕它们的工作流程。</p><h2 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to &quot;准备工作&quot;">​</a></h2><ol><li>IntelliJ IDEA 2025.2 或更高版本，并启用内置的 <strong>MCP Server</strong> 插件。</li><li>在 <kbd>Settings</kbd> &gt; <kbd>Tools</kbd> &gt; <kbd>MCP Server</kbd> 中打开服务器，然后按照 <a href="https://www.jetbrains.com/help/idea/mcp-server.html" target="_blank" rel="noreferrer">IntelliJ IDEA MCP Server 文档</a>连接你的客户端。</li><li>如果该页面列出了服务器暴露的工具，请确认 <code>easyapi_scan_endpoints</code> 和 <code>easyapi_export</code> 已启用。</li><li>对于 <code>easyapi_export</code>，需要先配置好 YApi —— 参见 <a href="/zh/settings/yapi">YApi 配置</a>。</li></ol><h2 id="扫描端点" tabindex="-1">扫描端点 <a class="header-anchor" href="#扫描端点" aria-label="Permalink to &quot;扫描端点&quot;">​</a></h2><p>Agent 通过 <code>classes</code>、<code>methods</code>（<code>ClassName#methodName</code>）或 <code>files</code>（相对于项目根目录的路径）指定目标，并通过 <code>projectPath</code> 指定项目（参见<a href="#选择项目">选择项目</a>）。只扫描指定的目标，使用与普通导出相同的扫描器和规则；所有目标都必须能解析，否则什么都不扫描。没有端点的目标——请求或响应模型、Service、未映射的方法、或导出失败的类（见 <code>idea.log</code>）——会带上原因列在 <code>skipped</code> 中；如果你改动过模型或 Service，请改用使用它们的控制器或方法。</p><h3 id="在-ide-之外改动的文件" tabindex="-1">在 IDE 之外改动的文件 <a class="header-anchor" href="#在-ide-之外改动的文件" aria-label="Permalink to &quot;在 IDE 之外改动的文件&quot;">​</a></h3><p>在目标解析之前，IDE 会从磁盘加载目标所在的文件，以及它已注意到的项目根目录下的其他改动，因此 Agent 刚写完文件就发起的调用能看到新内容。对于在 IDE 之外创建的类，通过 <code>files</code> 传入它的文件。</p><ul><li><strong>IDE 中未保存的改动会中止调用</strong>（<code>UNSAVED_IN_IDE</code>）：当它们位于待扫描文件中，或位于项目根目录下另一个同时在磁盘上改动过的文件中时。保存它们，或用 <strong>File | Reload from Disk</strong> 丢弃 IDE 中的改动。</li><li>**IntelliJ IDEA 2025.2 中，模态对话框会中止调用。**该版本只在没有模态对话框（如 Settings）打开时加载文件，因此调用会在约 10 秒后以 <code>SYNC_TIMEOUT</code> 失败，即使没有任何文件改动。更高版本在对话框打开时也能加载文件。</li><li>**限制：**与目标一起改动的请求或响应类可能尚未重新加载，或在项目根目录之外完全不会重新加载：将它的文件加入 <code>files</code>（根目录之外的，将类名加入 <code>classes</code>）；它会如预期出现在 <code>skipped</code> 中。不是目标、在编辑器中有未保存改动、同时在磁盘上改动过的文件，可能按编辑器显示的内容被扫描：调用前请先保存。</li></ul><h2 id="导出到-yapi" tabindex="-1">导出到 YApi <a class="header-anchor" href="#导出到-yapi" aria-label="Permalink to &quot;导出到 YApi&quot;">​</a></h2><p><code>easyapi_export</code> 与扫描工具一样接收目标（含同步），然后运行 <strong>Export to YAPI</strong> 的导出，使用相同的规则、服务器和导出模式，且无任何对话框。<code>channel</code> 为 <code>yapi</code>，是默认值，也是目前唯一的值。导出陈旧代码仍会成功，因此请注意上述限制。</p><h3 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Token&quot;">​</a></h3><p>调用不会向你询问任何东西：缺失的服务器或 Token 会直接体现在返回结果中。</p><ol><li>在 <kbd>Settings</kbd> &gt; <kbd>Other Settings</kbd> &gt; <kbd>EasyApi</kbd> &gt; <kbd>YApi</kbd> 中填写 <strong>Yapi Server</strong>。</li><li>通过 <code>options.token</code> 传入 Token（先用 YApi 校验，从不保存；该调用的所有端点都会进入此 Token 对应的项目），或在同一页面的 <strong>Tokens</strong> 下添加 <code>&lt;destination&gt;=&lt;token&gt;</code>。端点的目标位置由它的 <code>yapi.project</code> 规则决定（内置规则将 <code>@project</code> 和 <code>@module</code> 文档标签映射到该规则），否则取其类的模块，再否则取项目名。</li></ol><h3 id="写入结果" tabindex="-1">写入结果 <a class="header-anchor" href="#写入结果" aria-label="Permalink to &quot;写入结果&quot;">​</a></h3><p>返回结果中每个端点对应一项：</p><ul><li><code>updated</code>：具有相同路径和方法的 API 被覆盖。YApi 在整个项目中按路径和方法匹配，因此在其他目录中的同名 API 会被移入目标目录（<code>movedFrom</code>），无论导出模式如何；该目录可能被置空。</li><li><code>created</code>：保存前在 YApi 项目中未找到同名 API。</li><li><code>not_written</code>：由 <strong>Export Mode</strong> 保留（<code>NEVER_UPDATE</code>，或 <code>UPDATE_IF_CHANGED</code> 且无变化时；<code>ALWAYS_ASK</code> 视为同意），或未被 YApi 接受（如 gRPC 端点）；<code>reason</code> 会说明是哪一种。</li><li><code>failed</code>：<code>reason</code> 说明原因；没有 Token 的目标位置只会让该位置的端点失败。只要有一个端点未失败，调用即视为成功，因此 <code>failed</code> 大于 0 表示部分导出。</li></ul><p>不会出现对话框或成功通知；与普通导出一样，规则失败的警告仍会出现。</p><h2 id="选择项目" tabindex="-1">选择项目 <a class="header-anchor" href="#选择项目" aria-label="Permalink to &quot;选择项目&quot;">​</a></h2><p>每次调用都传入 <code>projectPath</code>：项目根目录或其中任意位置的绝对路径，例如 Agent 的工作目录。包含它的最内层已打开项目会应答，且每个成功结果中的 <code>project</code> 会指明该项目。不传 <code>projectPath</code> 时，若打开了多个项目，调用会以 <code>PROJECT_AMBIGUOUS</code> 失败；若只打开一个项目，IntelliJ IDEA 2025.2 会接受。更高版本的 IDE 会在工具运行前检查项目，并用它们自己的错误文本拒绝无法定位的调用，而不是返回 <code>{&quot;error&quot;: …}</code> 结果。</p><h2 id="错误码" tabindex="-1">错误码 <a class="header-anchor" href="#错误码" aria-label="Permalink to &quot;错误码&quot;">​</a></h2><p>调用失败时返回 <code>{&quot;error&quot;: {&quot;code&quot;: …, &quot;message&quot;: …}}</code> 而不是结果；message 会说明该如何处理。</p><table tabindex="0"><thead><tr><th><code>code</code></th><th>含义</th></tr></thead><tbody><tr><td><code>TARGETS_REQUIRED</code></td><td>未指定任何目标。</td></tr><tr><td><code>TARGETS_UNRESOLVED</code></td><td>有目标无法解析；<code>failures</code> 逐个列出。</td></tr><tr><td><code>NO_ENDPOINTS</code></td><td>没有目标能产生端点；<code>skipped</code> 说明原因。</td></tr><tr><td><code>TARGETS_CHANGED</code></td><td>目标在扫描过程中发生变化。请重试。</td></tr><tr><td><code>INDEX_NOT_READY</code></td><td>IDE 正在索引（如在大量文件一次性在 IDE 外改动后）。索引完成后重试。</td></tr><tr><td><code>UNSAVED_IN_IDE</code></td><td>列出的 <code>files</code> 在 IDE 中有未保存的改动。保存或重新加载后重试。</td></tr><tr><td><code>SYNC_TIMEOUT</code></td><td>IDE 未能在 10 秒内加载在 IDE 之外改动的文件。重试；若再次超时，请关闭 IDE 中打开的模态对话框（如 Settings），稍后重试。</td></tr><tr><td><code>CHANNEL_NOT_FOUND</code></td><td>导出：未知渠道；<code>channels</code> 列出可导出的渠道。</td></tr><tr><td><code>CHANNEL_NOT_SUPPORTED</code></td><td>导出：该渠道需要对话框；<code>channels</code> 列出可导出的渠道。</td></tr><tr><td><code>CHANNEL_DISABLED</code></td><td>导出：请在 <kbd>Settings</kbd> &gt; <kbd>Other Settings</kbd> &gt; <kbd>EasyApi</kbd> &gt; <kbd>Features</kbd> 中打开该渠道。</td></tr><tr><td><code>OPTIONS_INVALID</code></td><td>导出：未知选项或空值；<code>acceptedOptions</code> 列出可接受的选项。</td></tr><tr><td><code>EXPORT_FAILED</code></td><td>导出：什么都没写入；<code>items</code> 在已知时逐个列出端点。</td></tr><tr><td><code>PROJECT_AMBIGUOUS</code></td><td>打开了多个项目且未传 <code>projectPath</code>。</td></tr><tr><td><code>PROJECT_NOT_FOUND</code></td><td>没有已打开的项目包含 <code>projectPath</code>。</td></tr><tr><td><code>INTERNAL_ERROR</code></td><td>发生了意外错误；见 <code>idea.log</code>。</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Token 与 idea.log</p><p>Token 不会出现在返回结果、错误信息或工具写入 EasyYapi 控制台的内容中。但 EasyYapi 的 HTTP 日志会把每个请求地址写入 <code>idea.log</code>，而 YApi 的 GET 请求地址中带有 Token，因此导出使用过的 Token（传入的或来自 Token 表的）会以明文落入 <code>idea.log</code>，与在 IDE 中使用 <strong>Export to YAPI</strong> 相同。</p></div>',26)])])}const _=d(a,[["render",r]]);export{E as __pageData,_ as default};
